const data = $input.first().json;

const outageStart = new Date(data.actual_start ?? data.planned_start);
const outageEnd   = new Date(data.actual_end   ?? data.planned_end);
const workingHours = data.working_hours;

function getKyivDateString(date) {
  const formatter = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Kyiv',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  return formatter.format(date);
}

function getKyivDayName(date) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Europe/Kyiv',
    weekday: 'long'
  });
  return formatter.format(date).toLowerCase();
}

function getKyivOffsetMinutes(dateStr) {
  const formatter = new Intl.DateTimeFormat('en', {
    timeZone: 'Europe/Kyiv',
    timeZoneName: 'longOffset'
  });
  const parts = formatter.formatToParts(new Date(`${dateStr}T12:00:00Z`));
  const tzName = parts.find(p => p.type === 'timeZoneName')?.value ?? 'GMT+02:00';
  const match  = tzName.match(/GMT([+-])(\d{2}):(\d{2})/);
  if (!match) return 120;
  const sign = match[1] === '+' ? 1 : -1;
  return sign * (parseInt(match[2]) * 60 + parseInt(match[3]));
}

function toUtcDate(dateStr, timeStr) {
  const offsetMins = getKyivOffsetMinutes(dateStr);
  const [h, m] = timeStr.split(':').map(Number);
  const minutesUtc = (h * 60 + m) - offsetMins;
  const result = new Date(`${dateStr}T00:00:00Z`);
  result.setUTCMinutes(result.getUTCMinutes() + minutesUtc);
  return result;
}

let totalDuration = 0;
let firstSessionStart = null;
let lastSessionEnd = null;

const startKyivStr = getKyivDateString(outageStart);
const endKyivStr = getKyivDateString(outageEnd);

let currentKyivDate = new Date(`${startKyivStr}T12:00:00Z`);
const endKyivDate = new Date(`${endKyivStr}T12:00:00Z`);

while (currentKyivDate <= endKyivDate) {
  const currentStr = getKyivDateString(currentKyivDate);
  const dayName = getKyivDayName(currentKyivDate);

  const schedule = workingHours[dayName];
  if (schedule && schedule.isOpen) {
    const workOpen = toUtcDate(currentStr, schedule.start);
    let workClose = toUtcDate(currentStr, schedule.end);

    if (workClose <= workOpen && schedule.end === "00:00") {
      workClose = new Date(workClose.getTime() + 24 * 60 * 60 * 1000);
    }

    const segStart = new Date(Math.max(outageStart.getTime(), workOpen.getTime()));
    const segEnd = new Date(Math.min(outageEnd.getTime(), workClose.getTime()));

    if (segStart < segEnd) {
      const durationHours = (segEnd - segStart) / (1000 * 60 * 60);
      totalDuration += durationHours;
      if (!firstSessionStart) firstSessionStart = segStart.toISOString();
      lastSessionEnd = segEnd.toISOString();
    }
  }

  currentKyivDate.setUTCDate(currentKyivDate.getUTCDate() + 1);
}

return [{
  json: {
    outage_log_id:  data.outage_log_id,
    location_id:    data.location_id,
    company_id:     data.company_id,
    location_name:  data.location_name,
    duration_hours: Math.round(totalDuration * 1000) / 1000,
    session_start:  firstSessionStart,
    session_end:    lastSessionEnd
  }
}];

const intersection = $('Calculate intersection').item.json;
const generators = $input.all();

return generators.map(g => {
  const gen = g.json;

  // Парсимо всі числові поля з рядків
  const accumulatedHours       = parseFloat(gen.accumulated_hours)        || 0;
  const hoursSinceService      = parseFloat(gen.hours_since_last_service) || 0;
  const currentFuel            = parseFloat(gen.current_fuel_litres)      || 0;
  const consumptionPerHour     = parseFloat(gen.consumption_per_hour)     || 0;
  const loadFactor             = parseFloat(gen.load_factor)              || 0.75;
  const tankVolume             = parseFloat(gen.tank_volume_litres)       || 0;
  const maintenanceInterval    = parseFloat(gen.maintenance_interval_hours) || 50;

  const fuelConsumed = Math.round(
    intersection.duration_hours * consumptionPerHour * loadFactor * 1000
  ) / 1000;

  const newFuelLitres = Math.max(
    Math.round((currentFuel - fuelConsumed) * 100) / 100,
    0
  );

  return {
    json: {
      generator_id:   gen.generator_id,
      outage_log_id:  intersection.outage_log_id,
      location_id:    intersection.location_id,
      company_id:     intersection.company_id,

      session_start:  intersection.session_start,
      session_end:    intersection.session_end,
      duration_hours: intersection.duration_hours,
      fuel_consumed:  fuelConsumed,

      new_accumulated_hours:        Math.round((accumulatedHours + intersection.duration_hours) * 100) / 100,
      new_hours_since_last_service: Math.round((hoursSinceService + intersection.duration_hours) * 100) / 100,
      new_fuel_litres:              newFuelLitres,
      fuel_went_negative:           (currentFuel - fuelConsumed) < 0,

      tank_volume_litres:         tankVolume,
      maintenance_interval_hours: maintenanceInterval,
      consumption_per_hour:       consumptionPerHour
    }
  };
});

